"""OpenAI implementation of the provider-neutral reasoning contract."""

import json
from typing import Any

from pydantic import BaseModel, ConfigDict, Field

from the_a_team.providers.base import (
    ProviderError,
    ReasoningRequest,
    ReasoningResponse,
)
from the_a_team.schemas import (
    AgentRole,
    OrchestrationPlan,
    ReviewResult,
)


class _OpenAIArtifactOutput(BaseModel):
    """Strict artifact fields generated by OpenAI."""

    model_config = ConfigDict(extra="forbid")

    title: str = Field(min_length=1)
    summary: str = Field(min_length=1)
    content: str = Field(min_length=1)


_OUTPUT_MODELS: dict[AgentRole, type[BaseModel]] = {
    AgentRole.ORCHESTRATOR: OrchestrationPlan,
    AgentRole.ENGINEER: _OpenAIArtifactOutput,
    AgentRole.REVIEWER: ReviewResult,
}

_SYSTEM_PROMPTS: dict[AgentRole, str] = {
    AgentRole.ORCHESTRATOR: (
        "You are the orchestrator. Classify the request and create an execution plan. "
        "Do not perform the engineering work."
    ),
    AgentRole.ENGINEER: (
        "You are the engineer. Produce the requested artifact from the supplied plan "
        "and revision feedback."
    ),
    AgentRole.REVIEWER: (
        "You are the reviewer. Evaluate the artifact independently and return a "
        "PASS or REVISE decision."
    ),
}


class OpenAIProvider:
    """Generate role-specific structured output with the OpenAI Responses API."""

    def __init__(
        self,
        *,
        model: str,
        api_key: str | None = None,
        client: Any | None = None,
    ) -> None:
        if not model.strip():
            raise ValueError("OpenAI model name cannot be empty.")

        if client is None:
            try:
                from openai import OpenAI
            except ImportError as error:
                raise ProviderError(
                    "The OpenAI SDK is not installed. Install the project dependencies."
                ) from error
            client = OpenAI(api_key=api_key)

        self._model = model
        self._client = client

    @property
    def name(self) -> str:
        return "openai"

    def generate(self, request: ReasoningRequest) -> ReasoningResponse:
        output_model = _OUTPUT_MODELS[request.role]
        user_input = json.dumps(
            {
                "objective": request.objective,
                "context": request.context,
            },
            sort_keys=True,
        )

        try:
            response = self._client.responses.parse(
                model=self._model,
                input=[
                    {
                        "role": "system",
                        "content": _SYSTEM_PROMPTS[request.role],
                    },
                    {
                        "role": "user",
                        "content": user_input,
                    },
                ],
                text_format=output_model,
            )
        except Exception as error:
            raise ProviderError(
                f"OpenAI request failed for the {request.role.value} agent."
            ) from error

        parsed = response.output_parsed
        if not isinstance(parsed, BaseModel):
            raise ProviderError(
                f"OpenAI returned no structured output for the {request.role.value} agent."
            )

        return ReasoningResponse(
            content=response.output_text,
            structured_output=parsed.model_dump(mode="json"),
        )
